INSERT INTO `courses` (`id`, `title`, `category_id`, `description`, `image`, `price`, `created_at`) VALUES
(3, 'COMPUTER FUNDAMENTALS', 6, '<h2><strong>COURSE DESCRIPTION</strong></h2><p><br></p><ul><li>Fundamentals of Computers</li></ul><p><br></p><ul><li>Computer Hardware and Software</li></ul><p><br></p><ul><li>Input and Output Devices</li></ul><p><br></p><ul><li>Memory and Storage Devices</li></ul><p><br></p><ul><li>Operating Systems</li></ul><p><br></p><ul><li>Computer Networks and Internet</li></ul><p><br></p><ul><li>MS Office (Word, Excel, PowerPoint)</li></ul><p><br></p><ul><li>Database Management Systems</li></ul><p><br></p><ul><li>Computer Security and Cyber Safety</li></ul><p><br></p><ul><li>Programming Concepts</li></ul><p><br></p><ul><li>Number System and Binary Arithmetic</li></ul><p><br></p><ul><li>BIOS, UEFI, Firmware, and Booting Process</li></ul><p><br></p><ul><li>Cloud Computing</li></ul><p><br></p><ul><li>Artificial Intelligence and Emerging Technologies</li></ul><p><br></p><ul><li>Computer Abbreviations and Terminologies</li></ul><p><br></p><ul><li>Covers fundamental to advanced Computer concepts.</li></ul><p><br></p><ul><li>Chapter-wise, Topic-wise, and Full-Length Mock Tests.</li></ul><p><br></p><ul><li>Questions prepared according to the latest exam pattern and syllabus.</li></ul><p><br></p><ul><li>Suitable for <strong>SSC, Railway, Banking, State PSC, UPSC, CUET, Computer Operator, Data Entry Operator, and other competitive exams</strong>.</li></ul><p><br></p><ul><li>Includes objective, conceptual, and application-based questions.</li></ul>', , 20.00, '2025-10-13 15:04:57');
INSERT INTO `courses` (`id`, `title`, `category_id`, `description`, `image`, `price`, `created_at`) VALUES
(24, 'ADVANCE MATH', 26, '<h2>COURSE DESCRIPTION</h2><p><br></p><p><br></p><h3>Algebra</h3><ul><li>Linear Equations</li><li>Quadratic Equations</li><li>Identities</li><li>Surds and Indices</li><li>Polynomials</li></ul><h3>Geometry</h3><ul><li>Lines and Angles</li><li>Triangles</li><li>Quadrilaterals</li><li>Circles</li><li>Coordinate Geometry</li></ul><h3>Mensuration</h3><ul><li>Area and Perimeter</li><li>Surface Area and Volume</li><li>2D and 3D Figures</li></ul><h3>Trigonometry</h3><ul><li>Trigonometric Ratios</li><li>Heights and Distances</li><li>Trigonometric Identities</li></ul><h3>Data Interpretation &amp; Statistics</h3><ul><li>Bar Graphs</li><li>Pie Charts</li><li>Line Graphs</li><li>Tabular Data</li><li>Mean, Median, Mode</li><li>Chapter-wise, Topic-wise, and Full-Length Mock Tests.</li></ul><p><br></p><ul><li>Questions based on the latest examination patterns and difficulty levels.</li></ul><p><br></p><ul><li>Suitable for <strong>SSC CGL, SSC CHSL, SSC CPO, Railway, Banking, Defence, State PSC, CUET, CAT Foundation, and other competitive exams</strong>.</li></ul><p><br></p><ul><li>Includes basic, moderate, and advanced-level questions.</li></ul><p><br></p><ul><li>Detailed solutions with step-by-step explanations.</li></ul>', , 15.00, '2026-04-20 10:05:22');
INSERT INTO `courses` (`id`, `title`, `category_id`, `description`, `image`, `price`, `created_at`) VALUES
(25, 'BIOLOGY (BIO SCIENCE)', 26, '<h2>Course Highlights</h2><p><br></p><ul><li>Comprehensive Biology Test Series designed for competitive examinations.</li></ul><p><br></p><ul><li>Covers the complete Biology syllabus including <strong>Botany and Zoology</strong>.</li></ul><p><br></p><ul><li>Chapter-wise, Unit-wise, and Full-Length Mock Tests.</li></ul><p><br></p><ul><li>Questions based on the latest examination pattern and syllabus.</li></ul><p><br></p><ul><li>Suitable for <strong>NEET, CUET, Nursing, Paramedical, SSC, Railway, and other Biology-based exams</strong>.</li></ul><p><br></p><ul><li>Detailed solutions and explanations for every question.</li></ul><p><br></p><ul><li>Performance analysis to identify strengths and weak areas.</li></ul><p><br></p><ul><li>Time-bound tests to improve speed and accuracy.</li></ul><p><br></p><ul><li>Multiple revision tests for better retention of concepts.</li></ul><p><br></p><ul><li>Focus on NCERT-based as well as application-oriented questions.</li></ul><p><br></p><ul><li>Regular updates and new test papers.</li></ul><p><br></p><ul><li>Instant scorecard and ranking system.</li></ul><p><br></p><ul><li>Designed by experienced Biology faculty and subject experts.</li></ul>', , 9.00, '2026-04-24 07:44:39');
